class VaultError(Exception):
    pass


class VaultMissingKey(VaultError):
    pass


def _secrets_dir() -> Path:
    return _paths.manager_home() / "secrets" / "servers"


def _keychain_read() -> str | None:
    try:
        result = subprocess.run(
            ["security", "find-generic-password",
             "-s", _KEYCHAIN_SERVICE, "-a", _KEYCHAIN_ACCOUNT, "-w"],
            capture_output=True, text=True, timeout=10,
        )
        if result.returncode == 0:
            return result.stdout.strip()
    except (subprocess.SubprocessError, OSError):
        pass
    return None


def _keychain_write(key_b64: str, *, force: bool = False) -> None:
    if force:
        subprocess.run(
            ["security", "delete-generic-password",
             "-s", _KEYCHAIN_SERVICE, "-a", _KEYCHAIN_ACCOUNT],
            capture_output=True, timeout=10,
        )
    subprocess.run(
        ["security", "add-generic-password",
         "-s", _KEYCHAIN_SERVICE, "-a", _KEYCHAIN_ACCOUNT, "-w", key_b64],
        capture_output=True, text=True, timeout=10, check=True,
    )


def load_master_key() -> bytes:
    """Load master key from env var, Keychain (macOS), or keyfile.

    Returns the raw Fernet key (base64-encoded 32 bytes).
    On non-macOS hosts a keyfile is auto-created if missing — server-side
    automation can't run ``vault-init`` interactively, and a brand-new
    install has no ciphertext yet, so generating one is safe.
    Raises VaultMissingKey only on macOS hosts that have neither env var
    nor a Keychain entry.
    """
    env_key = os.environ.get("AGENT_ML_MANAGER_VAULT_KEY")
    if env_key:
        return env_key.encode()

    if _is_macos():
        kc_key = _keychain_read()
        if kc_key:
            return kc_key.encode()

"""Symmetric encryption for secrets (Admin Tokens, API Keys).

Uses Fernet (AES-128-CBC + HMAC-SHA256) with a key derived from the machine ID.
Goal: prevent plain-text exposure if files are read by the Agent or leaked —
this is NOT a substitute for OS-level access control.
"""

from __future__ import annotations

import base64
import hashlib
import uuid
from pathlib import Path

from cryptography.fernet import Fernet, InvalidToken

# Deterministic salt — changing this invalidates all stored secrets.
_SALT = b"agent-ml-research-tum-v1"


def _derive_key() -> bytes:
    """Derive a Fernet key from the machine's MAC address + salt."""
    machine_id = str(uuid.getnode()).encode()
    raw = hashlib.pbkdf2_hmac("sha256", machine_id, _SALT, iterations=100_000, dklen=32)
    return base64.urlsafe_b64encode(raw)


_fernet: Fernet | None = None


def _get_fernet() -> Fernet:
    global _fernet
    if _fernet is None:
        _fernet = Fernet(_derive_key())
    return _fernet


def encrypt(plaintext: str) -> str:
    """Encrypt a string, return URL-safe base64 ciphertext."""
    return _get_fernet().encrypt(plaintext.encode()).decode()


def decrypt(ciphertext: str) -> str | None:
    """Decrypt ciphertext. Returns None if invalid/corrupted."""
    try:
        return _get_fernet().decrypt(ciphertext.encode()).decode()
    except (InvalidToken, Exception):
        return None


# --- File-level helpers (for admin token / API keys) ---

def save_secret(path: Path, plaintext: str) -> None:
    """Encrypt and write a secret to a file."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(encrypt(plaintext))


